import{_ as i,c as a,o as t,ag as n}from"./chunks/framework.D2yTFDqz.js";const u=JSON.parse('{"title":"2025.1.4","description":"","frontmatter":{"title":"2025.1.4"},"headers":[],"relativePath":"changelog/2025.1.3.md","filePath":"changelog/2025.1.3.md","lastUpdated":1765114933000}'),o={name:"changelog/2025.1.3.md"};function s(r,e,l,h,d,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="view-shadcn-ui-v2025-1-3-正式发布-新增ip输入框组件与多项功能增强" tabindex="-1">View Shadcn UI v2025.1.3 正式发布 - 新增IP输入框组件与多项功能增强 <a class="header-anchor" href="#view-shadcn-ui-v2025-1-3-正式发布-新增ip输入框组件与多项功能增强" aria-label="Permalink to &quot;View Shadcn UI v2025.1.3 正式发布 - 新增IP输入框组件与多项功能增强&quot;">​</a></h1><h2 id="🎉-版本信息-version-information" tabindex="-1">🎉 版本信息 / Version Information <a class="header-anchor" href="#🎉-版本信息-version-information" aria-label="Permalink to &quot;🎉 版本信息 / Version Information&quot;">​</a></h2><p><strong>版本号 / Version:</strong> 2025.1.3<br><strong>发布时间 / Release Date:</strong> 2025年5月27日 / May 27, 2025</p><h2 id="📖-项目简介-project-overview" tabindex="-1">📖 项目简介 / Project Overview <a class="header-anchor" href="#📖-项目简介-project-overview" aria-label="Permalink to &quot;📖 项目简介 / Project Overview&quot;">​</a></h2><p>View Shadcn UI 是一个基于 Tailwind CSS 构建的现代化 Vue3 组件库，致力于为开发者提供美观、易用、功能丰富的UI组件解决方案。</p><p>View Shadcn UI is a modern Vue3 component library built with Tailwind CSS, dedicated to providing developers with beautiful, user-friendly, and feature-rich UI component solutions.</p><h2 id="🔗-相关链接-links" tabindex="-1">🔗 相关链接 / Links <a class="header-anchor" href="#🔗-相关链接-links" aria-label="Permalink to &quot;🔗 相关链接 / Links&quot;">​</a></h2><ul><li><strong>项目地址 / Repository:</strong> <a href="https://github.com/devlive-community/view-shadcn-ui" target="_blank" rel="noreferrer">https://github.com/devlive-community/view-shadcn-ui</a></li><li><strong>官方网站 / Official Website:</strong> <a href="https://view-shadcn-ui.devlive.org/" target="_blank" rel="noreferrer">https://view-shadcn-ui.devlive.org/</a></li><li><strong>在线演练场 / Playground:</strong> <a href="https://playground.view-shadcn-ui.devlive.org/" target="_blank" rel="noreferrer">https://playground.view-shadcn-ui.devlive.org/</a></li></ul><h2 id="✨-本次更新亮点-highlights" tabindex="-1">✨ 本次更新亮点 / Highlights <a class="header-anchor" href="#✨-本次更新亮点-highlights" aria-label="Permalink to &quot;✨ 本次更新亮点 / Highlights&quot;">​</a></h2><h3 id="🆕-全新组件-new-components" tabindex="-1">🆕 全新组件 / New Components <a class="header-anchor" href="#🆕-全新组件-new-components" aria-label="Permalink to &quot;🆕 全新组件 / New Components&quot;">​</a></h3><h4 id="ip输入框组件-ip-input-component" tabindex="-1">IP输入框组件 (IP Input Component) <a class="header-anchor" href="#ip输入框组件-ip-input-component" aria-label="Permalink to &quot;IP输入框组件 (IP Input Component)&quot;">​</a></h4><p>我们新增了功能完整的IPv4地址输入框组件，支持：</p><ul><li>✅ <strong>IPv4地址支持</strong> - 专为IPv4地址格式设计，提供准确的输入验证</li><li>✅ <strong>灵活尺寸配置</strong> - 提供多种尺寸选择，适应不同场景需求</li><li>✅ <strong>表单集成</strong> - 完美融入表单验证体系</li><li>✅ <strong>自定义分隔符</strong> - 支持自定义IP地址分隔符样式</li><li>✅ <strong>禁用状态</strong> - 支持禁用状态，增强用户体验</li></ul><p>We&#39;ve introduced a comprehensive IPv4 address input component with support for:</p><ul><li>✅ <strong>IPv4 Address Support</strong> - Specifically designed for IPv4 format with accurate input validation</li><li>✅ <strong>Flexible Sizing</strong> - Multiple size options for different use cases</li><li>✅ <strong>Form Integration</strong> - Seamless integration with form validation</li><li>✅ <strong>Custom Separators</strong> - Customizable IP address separator styles</li><li>✅ <strong>Disabled State</strong> - Support for disabled state for better UX</li></ul><h3 id="🔧-组件功能增强-component-enhancements" tabindex="-1">🔧 组件功能增强 / Component Enhancements <a class="header-anchor" href="#🔧-组件功能增强-component-enhancements" aria-label="Permalink to &quot;🔧 组件功能增强 / Component Enhancements&quot;">​</a></h3><h4 id="流程组件-process-component" tabindex="-1">流程组件 (Process Component) <a class="header-anchor" href="#流程组件-process-component" aria-label="Permalink to &quot;流程组件 (Process Component)&quot;">​</a></h4><ul><li><strong>新增隐藏功能</strong> - 支持 <code>hiddenOnUsed</code> 配置项，可隐藏已使用的列，优化界面显示效果</li></ul><h4 id="数据构建组件-data-builder-component" tabindex="-1">数据构建组件 (Data Builder Component) <a class="header-anchor" href="#数据构建组件-data-builder-component" aria-label="Permalink to &quot;数据构建组件 (Data Builder Component)&quot;">​</a></h4><ul><li><strong>布局优化</strong> - 修复组件超越标尺的显示问题，确保界面布局的准确性和美观性</li></ul><h4 id="时间组件-time-component" tabindex="-1">时间组件 (Time Component) <a class="header-anchor" href="#时间组件-time-component" aria-label="Permalink to &quot;时间组件 (Time Component)&quot;">​</a></h4><ul><li><strong>实时更新</strong> - 支持配置更新间隔，实现时间的动态刷新显示</li><li><strong>相对时间</strong> - 新增相对时间显示功能（如&quot;3分钟前&quot;、&quot;1小时前&quot;等）</li><li><strong>国际化支持</strong> - 支持时间格式化和时区配置，满足全球化应用需求</li></ul><h4 id="通知中心组件-notification-center-component" tabindex="-1">通知中心组件 (Notification Center Component) <a class="header-anchor" href="#通知中心组件-notification-center-component" aria-label="Permalink to &quot;通知中心组件 (Notification Center Component)&quot;">​</a></h4><p>我们对通知中心组件进行了全面升级：</p><ul><li><strong>远程数据加载</strong> - 支持从远程API获取通知数据</li><li><strong>灵活定位</strong> - 支持多种位置配置选项</li><li><strong>尺寸定制</strong> - 支持自定义宽度和高度设置</li><li><strong>交互增强</strong> - 支持自定义触发器，提升用户交互体验</li><li><strong>插槽支持</strong> - 子项支持多个插槽，提供更大的自定义空间</li></ul><h2 id="🚀-技术改进-technical-improvements" tabindex="-1">🚀 技术改进 / Technical Improvements <a class="header-anchor" href="#🚀-技术改进-technical-improvements" aria-label="Permalink to &quot;🚀 技术改进 / Technical Improvements&quot;">​</a></h2><h3 id="enhanced-component-features" tabindex="-1">Enhanced Component Features: <a class="header-anchor" href="#enhanced-component-features" aria-label="Permalink to &quot;Enhanced Component Features:&quot;">​</a></h3><p><strong>Process Component:</strong></p><ul><li>Added <code>hiddenOnUsed</code> configuration to hide used columns for cleaner interfaces</li></ul><p><strong>Data Builder Component:</strong></p><ul><li>Fixed component overflow issues for better layout precision</li></ul><p><strong>Time Component:</strong></p><ul><li>Configurable update intervals for real-time display</li><li>Relative time display (e.g., &quot;3 minutes ago&quot;, &quot;1 hour ago&quot;)</li><li>Internationalization support with formatting and timezone configuration</li></ul><p><strong>Notification Center Component:</strong></p><ul><li>Remote data loading capabilities</li><li>Flexible positioning options</li><li>Customizable dimensions (width &amp; height)</li><li>Enhanced interaction with custom triggers</li><li>Multiple slot support for greater customization flexibility</li></ul><h2 id="📦-如何升级-how-to-upgrade" tabindex="-1">📦 如何升级 / How to Upgrade <a class="header-anchor" href="#📦-如何升级-how-to-upgrade" aria-label="Permalink to &quot;📦 如何升级 / How to Upgrade&quot;">​</a></h2><h3 id="npm" tabindex="-1">NPM <a class="header-anchor" href="#npm" aria-label="Permalink to &quot;NPM&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view-shadcn-ui@2025.1.3</span></span></code></pre></div><h3 id="yarn" tabindex="-1">Yarn <a class="header-anchor" href="#yarn" aria-label="Permalink to &quot;Yarn&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view-shadcn-ui@2025.1.3</span></span></code></pre></div><h3 id="pnpm" tabindex="-1">PNPM <a class="header-anchor" href="#pnpm" aria-label="Permalink to &quot;PNPM&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view-shadcn-ui@2025.1.3</span></span></code></pre></div><h2 id="🙏-致谢-acknowledgments" tabindex="-1">🙏 致谢 / Acknowledgments <a class="header-anchor" href="#🙏-致谢-acknowledgments" aria-label="Permalink to &quot;🙏 致谢 / Acknowledgments&quot;">​</a></h2><p>感谢所有为本次版本贡献代码和建议的开发者们！特别感谢 @qianmoQ 在本次版本中的大量贡献。</p><p>Thanks to all developers who contributed code and suggestions for this release! Special thanks to @qianmoQ for the significant contributions in this version.</p><h2 id="📢-反馈与支持-feedback-support" tabindex="-1">📢 反馈与支持 / Feedback &amp; Support <a class="header-anchor" href="#📢-反馈与支持-feedback-support" aria-label="Permalink to &quot;📢 反馈与支持 / Feedback &amp; Support&quot;">​</a></h2><p>如果您在使用过程中遇到任何问题或有改进建议，欢迎：</p><ul><li>在 GitHub 上提交 Issue</li><li>加入我们的社区讨论</li><li>访问官方文档获取详细使用指南</li></ul><p>If you encounter any issues or have suggestions for improvement, feel free to:</p><ul><li>Submit issues on GitHub</li><li>Join our community discussions</li><li>Visit our official documentation for detailed usage guides</li></ul><hr><p><strong>View Shadcn UI 团队</strong><br><strong>2025年5月27日</strong></p>',52)])])}const g=i(o,[["render",s]]);export{u as __pageData,g as default};
